-- Canonical CHECK parity: reviewed additive constraints only.
-- Quiesce writers and preserve a reviewed backup. All target metadata and invalid rows are checked before DDL.
-- DDL auto-commits; interrupted additions remain and exact replay resumes. No cross-ALTER rollback is claimed.
DELIMITER $$
BEGIN NOT ATOMIC
 IF DATABASE() IS NULL OR @@FOREIGN_KEY_CHECKS<>1 OR @@check_constraint_checks<>1 OR @@SESSION.sql_mode LIKE '%NO_BACKSLASH_ESCAPES%' OR (@@SESSION.sql_mode NOT LIKE '%STRICT_TRANS_TABLES%' AND @@SESSION.sql_mode NOT LIKE '%STRICT_ALL_TABLES%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='check_parity_session_state'; END IF;
 IF NOT ((SELECT COUNT(*) FROM (SELECT ENGINE,TABLE_COLLATION,CREATE_OPTIONS FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='form_config_versions' AND TABLE_TYPE='BASE TABLE') hb_check_rows)=1 AND NOT EXISTS(SELECT 1 FROM (SELECT ENGINE,TABLE_COLLATION,CREATE_OPTIONS FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='form_config_versions' AND TABLE_TYPE='BASE TABLE') hb_check_rows WHERE NOT ((BINARY `ENGINE` <=> BINARY 'InnoDB' AND BINARY `TABLE_COLLATION` <=> BINARY 'utf8mb4_unicode_ci' AND BINARY `CREATE_OPTIONS` <=> BINARY '')))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='check_parity_form_config_versions_options'; END IF;
