S_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL AND BINARY `COLUMN_COMMENT` <=> BINARY '') OR (BINARY `COLUMN_NAME` <=> BINARY 'revision' AND `ORDINAL_POSITION`=4 AND BINARY `COLUMN_DEFAULT` <=> BINARY '1' AND BINARY `IS_NULLABLE` <=> BINARY 'NO' AND BINARY `DATA_TYPE` <=> BINARY 'bigint' AND BINARY `COLUMN_TYPE` <=> BINARY 'bigint(20)' AND `CHARACTER_SET_NAME` IS NULL AND `COLLATION_NAME` IS NULL AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL AND BINARY `COLUMN_COMMENT` <=> BINARY '') OR (BINARY `COLUMN_NAME` <=> BINARY 'status' AND `ORDINAL_POSITION`=5 AND BINARY `COLUMN_DEFAULT` <=> BINARY '''draft''' AND BINARY `IS_NULLABLE` <=> BINARY 'NO' AND BINARY `DATA_TYPE` <=> BINARY 'varchar' AND BINARY `COLUMN_TYPE` <=> BINARY 'varchar(32)' AND BINARY `CHARACTER_SET_NAME` <=> BINARY 'utf8mb4' AND BINARY `COLLATION_NAME` <=> BINARY 'utf8mb4_nopad_bin' AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL AND BINARY `COLUMN_COMMENT` <=> BINARY '') OR (BINARY `COLUMN_NAME` <=> BINARY 'config_json' AND `ORDINAL_POSITION`=6 AND `COLUMN_DEFAULT` IS NULL AND BINARY `IS_NULLABLE` <=> BINARY 'NO' AND BINARY `DATA_TYPE` <=> BINARY 'longtext' AND BINARY `COLUMN_TYPE` <=> BINARY 'longtext' AND BINARY `CHARACTER_SET_NAME` <=> BINARY 'utf8mb4' AND BINARY `COLLATION_NAME` <=> BINARY 'utf8mb4_unicode_ci' AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL AND BINARY `COLUMN_COMMENT` <=> BINARY '') OR (BINARY `COLUMN_NAME` <=> BINARY 'reason' AND `ORDINAL_POSITION`=7 AND `COLUMN_DEFAULT` IS NULL AND BINARY `IS_NULLABLE` <=> BINARY 'NO' AND BINARY `DATA_TYPE` <=> BINARY 'longtext' AND BINARY `COLUMN_TYPE` <=> BINARY 'longtext' AND BINARY `CHARACTER_SET_NAME` <=> BINARY 'utf8mb4' AND BINARY `COLLATION_NAME` <=> BINARY 'utf8mb4_unicode_ci' AND BINARY `EXTRA` <=> BINARY '' AND BINARY `