ND BINARY `COLUMN_COMMENT` <=> BINARY '') OR (BINARY `COLUMN_NAME` <=> BINARY 'published_by' AND `ORDINAL_POSITION`=12 AND BINARY `COLUMN_DEFAULT` <=> BINARY 'NULL' AND BINARY `IS_NULLABLE` <=> BINARY 'YES' AND BINARY `DATA_TYPE` <=> BINARY 'varchar' AND BINARY `COLUMN_TYPE` <=> BINARY 'varchar(191)' AND BINARY `CHARACTER_SET_NAME` <=> BINARY 'utf8mb4' AND BINARY `COLLATION_NAME` <=> BINARY 'utf8mb4_unicode_ci' AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL AND BINARY `COLUMN_COMMENT` <=> BINARY '') OR (BINARY `COLUMN_NAME` <=> BINARY 'published_at' AND `ORDINAL_POSITION`=13 AND BINARY `COLUMN_DEFAULT` <=> BINARY 'NULL' AND BINARY `IS_NULLABLE` <=> BINARY 'YES' AND BINARY `DATA_TYPE` <=> BINARY 'bigint' AND BINARY `COLUMN_TYPE` <=> BINARY 'bigint(20)' AND `CHARACTER_SET_NAME` IS NULL AND `COLLATION_NAME` IS NULL AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL AND BINARY `COLUMN_COMMENT` <=> BINARY '') OR (BINARY `COLUMN_NAME` <=> BINARY 'last_request_id' AND `ORDINAL_POSITION`=14 AND `COLUMN_DEFAULT` IS NULL AND BINARY `IS_NULLABLE` <=> BINARY 'NO' AND BINARY `DATA_TYPE` <=> BINARY 'varchar' AND BINARY `COLUMN_TYPE` <=> BINARY 'varchar(191)' AND BINARY `CHARACTER_SET_NAME` <=> BINARY 'utf8mb4' AND BINARY `COLLATION_NAME` <=> BINARY 'utf8mb4_nopad_bin' AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL AND BINARY `COLUMN_COMMENT` <=> BINARY '')))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='check_parity_form_config_versions_columns'; END IF;
